/**
 * Editable page texts (Vocata CMS) — which CMS field holds which text.
 *
 * Every text is stored once per language as `<field>Da`, `<field>En`,
 * `<field>Nl` (house rules also `<field>De`). Its built-in value is the
 * message named by `ref` ("Namespace.key" in /messages), i.e. exactly what the
 * site shipped with.
 *
 * This file is the single source for three things:
 *  - the site (src/lib/prose.ts), which resolves the texts per page language,
 *  - the studio schemas  (schemas/<name>.json),  and
 *  - the seed content    (content/<name>.json),
 * the last two generated by `npm run cms:prose`. Keep it free of imports and
 * non-erasable TypeScript so Node can run the generator on it directly.
 */

export type Lang = "da" | "en" | "nl" | "de";
export type Ref = `${string}.${string}`;

export interface TextSpec {
  ref: Ref;
  title: string;
  /** Multi-line text box instead of a one-line input. */
  long?: boolean;
  description?: string;
}

export interface ListSpec {
  title: string;
  description?: string;
  /** Label of one entry in the studio. */
  itemTitle: string;
  /** The entry's text fields (titles shown in the studio). */
  fields: Record<string, { title: string; long?: boolean }>;
  /** One object per built-in entry: field → message ref. */
  rows: Record<string, Ref>[];
  /** Internal key per built-in entry (stored as `noegle`), e.g. for its icon. */
  keys?: string[];
}

export interface GroupSpec {
  title: string;
  description?: string;
  texts?: Record<string, TextSpec>;
  lists?: Record<string, ListSpec>;
}

export interface TypeSpec {
  name: string;
  title: string;
  preview: string;
  /** Languages stored per text. Default: da, en, nl. */
  langs?: Lang[];
  texts?: Record<string, TextSpec>;
  lists?: Record<string, ListSpec>;
  groups?: Record<string, GroupSpec>;
  /** Plain (not per-language) fields, shown first, and their seed values. */
  extra?: { fields: Record<string, unknown>[]; seed: Record<string, unknown> };
}

export const DEFAULT_LANGS: Lang[] = ["da", "en", "nl"];

export const SUFFIX: Record<Lang, string> = { da: "Da", en: "En", nl: "Nl", de: "De" };
export const LANG_LABEL: Record<Lang, string> = { da: "DK", en: "EN", nl: "NL", de: "DE" };

